custom_css:
/* 名片 · by kyuu */
/* ── 字体声明（本地优先） ── */
@font-face {
  font-family: 'LXGW WenKai';
  src: local('LXGW WenKai'), local('LXGWWenKai-Regular');
  font-weight: 400; font-style: normal; font-display: swap;
}
/* ── 设计变量（可自定义区） ── */
:root {
  --bg: #f2f3f7;                              /* 页面底色 */
  --card: rgba(255,255,255,0.68);
  --card-head: rgba(255,255,255,0.55);        /* 名字栏透明度 */
  --card-body: rgba(255,255,255,0.35);        /* 正文区透明度，越小越透 */
  --card-glass: rgba(255,255,255,0.45);       /* 底栏透明度 */
  --white: #FFF;
  --white-hover: #F0F0F2;
  --ink: #1a1a1a;                             /* 正文字色 */
  --ink-soft: #444;
  --meta: #7a7a7a;                            /* 时间/楼层等辅助字色 */
  --name: #111;                               /* 名字颜色 */
  --line: rgba(0,0,0,0.06);
  --accent: #555;
  --sans: -apple-system, system-ui, 'Segoe UI', Roboto, sans-serif;
  --cjk:'LXGW WenKai', serif;                /* 中文字体，可换 */
  --mono: 'SF Mono', 'Cascadia Code', 'Fira Code', monospace;
  --pad: 1.15rem;
  --avatar: 3.6rem;                           /* 头像大小 */
  --radius: 14px;                             /* 卡片圆角 */
  --blur: 18px;                               /* 毛玻璃模糊强度 */
  --foot-h: 2.8rem;
  --shadow: 0 1px 3px rgba(0,0,0,0.03), 0 6px 24px rgba(0,0,0,0.045);
  /* ⭕ 横幅图片 — 替换链接即可 */
  --banner-bot: url('https://files.catbox.moe/jnejgc.png');
  --banner-user: url('https://files.catbox.moe/jnejgc.png');
  --banner-h: 120px;                          /* 横幅高度 */
  font-size: clamp(13px, 0.85vw + 9px, 15.5px);
  --SmartThemeBodyColor: #1a1a1a;
  --SmartThemeBorderColor: rgba(0,0,0,0.06);
  --SmartThemeBlurTintColor: rgba(255,255,255,0.75);
  --SmartThemeChatTintColor: transparent;
  --SmartThemeQuoteColor: #7a7a7a;
  --SmartThemeFastUIBGColor: #f2f3f7;
  --SmartThemeUserMesBlurTintColor: rgba(255,255,255,0.75);
  --SmartThemeBotMesBlurTintColor: rgba(255,255,255,0.75);
  --SmartThemeEmColor: #7a7a7a;
  --SmartThemeShadowColor: rgba(0,0,0,0.04);
}
/* ── 全局 ── */
::-webkit-scrollbar { display: none }
html, body { scrollbar-width: none }
body, body.no-blur { background: var(--bg) }
/* ⭕ 背景渐变色斑 — 改 rgba 值可换色调 */
body:not([style*="background"]) {
  background:
    radial-gradient(ellipse 130% 80% at 10% 15%, rgba(180,200,240,0.35), transparent 55%),
    radial-gradient(ellipse 100% 70% at 90% 85%, rgba(210,180,230,0.25), transparent 50%),
    radial-gradient(ellipse 80% 60% at 50% 50%, rgba(200,220,210,0.15), transparent 60%),
    var(--bg);
  background-attachment: fixed;
}
#bg1 { filter: brightness(1.03) saturate(1.05) }
#sheld, #chat { background: transparent !important }
::selection { background: rgba(0,0,0,0.07); color: var(--ink); text-shadow: none }
body.no-blur :is(#chat .mes .ch_name, #chat .mes .mes_text,
#chat .mes .mes_block::after, #form_sheld, #top-bar) {
  backdrop-filter: blur(var(--blur));-webkit-backdrop-filter: blur(var(--blur));
}
/* ── 白底面板统一 ── */
:is(.drawer-content, #top-settings-holder, #right-nav-panel, #left-nav-panel,
.dialogue_popup, .dialogue_popup_large, #dialogue_popup, #shadow_popup,
.popup:not(.tobepurged), .ui-widget-content, #select_chat_popup,
#character_popup, #export_format_popup, .openai_logit_bias_list,
#movingUIPresets, .list-group, .text_pole_row,
.options-content, .ctx-menu) {
  background: var(--white) !important;
  color: var(--ink) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}
:is(#top-bar, #form_sheld, #send_form,
.range-block, .range-block-title,
.title_restorable, h3, h4,
.menu_button, .drawer-icon,
textarea, input[type="text"],
.list-group-item, .ctx-item, .ctx-header) {
  background: var(--white) !important;
  background-image: none !important;
  color: var(--ink) !important;
  border-color: var(--line) !important;text-shadow: none !important;
}
:is(.list-group-item, .ctx-item,
.inline-drawer-toggle, .inline-drawer-header,
.menu_button, .drawer-icon):hover {
  background: var(--white-hover) !important;color: var(--ink) !important;
}
/* ── 顶栏 ── */
#top-bar {
  background: rgba(255,255,255,0.92) !important;
  backdrop-filter: blur(20px); -webkit-backdrop-filter: blur(20px);
  border-bottom: 1px solid var(--line);
  box-shadow: 0 1px 8px rgba(0,0,0,0.02);
}
:is(.drawer-content, #right-nav-panel, #left-nav-panel):is(.inline-drawer, .inline-drawer-content, .range-block) {
  background: transparent !important;
}
/* ── 世界书面板 ── */
:is(#WorldInfo, #world_info_panel, .wi-holder) {
  background: var(--white) !important;
  color: var(--ink) !important;
}
:is(#WorldInfo, #world_info_panel, .wi-holder) *:not([class*="fa-"]) {
  background: var(--white) !important;
  color: var(--ink) !important;
  border-color: var(--line) !important;
}
.world_entry {
  background: var(--bg) !important;
  border: 1px solid var(--line) !important;
  border-radius: 4px;
}
.world_entry_form, .world_entry_block {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}
#WorldInfo .inline-drawer-content,
#WorldInfo .inline-drawer,
#WorldInfo .range-block {
  background: transparent !important;
}
/* ── Select2 下拉 ── */
:is(.select2-dropdown, .select2-results, .select2-container--open) *:not([class*="fa-"]) {
  background: var(--white) !important;
  color: var(--ink) !important;
  border-color: var(--line) !important;
}
.select2-container { background: transparent !important; border: none !important }
.select2-selection {
  background: var(--white) !important;
  color: var(--ink) !important;
  border: 1px solid #ddd !important;
}
.select2-container--open .select2-dropdown {
  border: 1px solid #ddd !important;
  box-shadow: 0 2px 8px rgba(0,0,0,0.08) !important;
}
.select2-results__option--highlighted[aria-selected],
.select2-results__option:hover {
  background: var(--white-hover) !important;
}
.select2-results__option[aria-selected="true"] {
  background: #f0f0f2 !important;
}
select, select option {
  background: var(--white) !important;
  color: var(--ink) !important;
}
/* ── 聊天区 ── */
#chat {
  display: flex; flex-direction: column; align-items: center;
  padding: 1.5rem 1rem 3rem;
}
#chat .mes::before, #chat .mes::after { display: none }
#chat .mes[is_user='true'] + .mes[is_user='false'],
#chat .mes[is_user='false'] + .mes[is_user='true'] {
  margin-top: 1.6rem !important;
}
/* ── 卡片（透明壳，不模糊，子元素各自模糊） ── */
#chat .mes {
  display: block; position: relative;
  width: 100%; max-width: 88%;
  margin: 0 auto 0.9rem !important;
  border: 1px solid rgba(255,255,255,0.5);
  border-radius: var(--radius); padding: 0;
  box-sizing: border-box; min-height: unset; overflow: visible;
  background: transparent;
  backdrop-filter: none; -webkit-backdrop-filter: none;
  box-shadow: var(--shadow); text-align: left; float: none !important;
}
/* ── 头像 ── */
#chat .mes .mesAvatarWrapper {
  position: absolute; top: 0; left: 0; width: 100%; height: 100%;
  overflow: visible; z-index: 10; margin: 0; padding: 0;
  border: none; background: none; pointer-events: none;
}
#chat .mes .mesAvatarWrapper .avatar {
  position: absolute !important;
  top: calc(var(--banner-h) - var(--avatar) / 2 + 0.3rem) !important;
  left: var(--pad) !important;
  width: var(--avatar) !important; height: var(--avatar) !important;
  border: none !important; border-radius: 50% !important;
  padding: 0 !important; margin: 0 !important;
  background: none; box-shadow: none; pointer-events: auto; z-index: 15;
}
#chat .mes .mesAvatarWrapper .avatar img {
  width: 100%; height: 100%; object-fit: cover;
  border-radius: 50%; display: block;
  box-shadow:
    0 0 0 3px rgba(255,255,255,0.9),
    0 0 0 4px rgba(0,0,0,0.06),
    0 2px 8px rgba(0,0,0,0.08);
}
/* 底栏元信息 */
#chat .mes .mesAvatarWrapper :is(.mesIDDisplay, .mes_timer, .tokenCounterDisplay) {
  display: block !important; position: absolute !important;
  bottom: calc(var(--foot-h) / 2 - 0.1rem) !important;
  top: auto !important; width: auto !important;
  text-align: left; font: 400 0.68rem/1.3 var(--cjk) !important;
  color: var(--meta) !important; background: none !important;
  border: none !important; padding: 0 !important; margin: 0 !important;
  opacity: 0.7; z-index: 5;
}
#chat .mes .mesAvatarWrapper .mesIDDisplay        { left: calc(var(--pad) + 5.2rem) !important; pointer-events: none }
#chat .mes .mesAvatarWrapper .mes_timer           { left: calc(var(--pad) + 7.5rem); pointer-events: auto }
#chat .mes .mesAvatarWrapper .tokenCounterDisplay { left: calc(var(--pad) + 11.5rem); pointer-events: auto }
:is(.mesIDDisplay, .mes_timer, .tokenCounterDisplay):empty { display: none !important }
/* ── Swipe 翻页 ── */
#chat .mes .swipe_left,
#chat .mes .swipe_right {
  position: absolute !important;
  bottom: calc(var(--foot-h) / 2 - 0.45rem) !important;
  top: auto !important; left: auto !important;
  color: var(--meta); opacity: 0.3; width: 1.6rem !important; height: 1.6rem !important;
  margin: 0 !important; padding: 0 !important;
  display: flex !important; align-items: center; justify-content: center; z-index: 5;
}
#chat .mes .swipe_left  { right: calc(var(--pad) + 4.2rem) !important }
#chat .mes .swipe_right { right: var(--pad) !important }
#chat .mes .swipes-counter {
  position: absolute !important;
  bottom: calc(var(--foot-h) / 2 - 0.1rem) !important;
  right: calc(var(--pad) + 2.2rem) !important;
  left: auto !important; top: auto !important;
  font: 400 0.68rem/1.3 var(--cjk) !important;
  color: var(--meta); opacity: 0.7;
  margin: 0 !important; padding: 0 !important;
  width: auto !important; height: auto !important; text-align: center;
}
/* ── mes_block 内容块 ── */
#chat .mes .mes_block {
  display: flex; flex-direction: column; width: 100%;
  padding: 0; margin: 0; min-height: auto;
  background: none; border: none; box-shadow: none;
}
/* ⭕ 横幅图 — 图片在变量区改，高度改 --banner-h */
#chat .mes .mes_block::before {
  content: ''; display: block !important;
  width: 100%; height: var(--banner-h);
  background: center/cover no-repeat;
  border-radius: var(--radius) var(--radius) 0 0;
  box-sizing: border-box; flex-shrink: 0;
}
#chat .mes[is_user='false'] .mes_block::before { background-image: var(--banner-bot) }
#chat .mes[is_user='true']  .mes_block::before { background-image: var(--banner-user) }
/* ⭕ 底部装饰栏 — 改 content 换符号 */
#chat .mes .mes_block::after {
  content: '♡◇↗'; display: flex; align-items: center;
  padding: 0.3rem calc(var(--pad) + 0.1rem);
  font-size: 0.9rem; letter-spacing: 0.04em;
  color: var(--meta); opacity: 0.35;
  background: var(--card-glass);
  backdrop-filter: blur(var(--blur)) saturate(1.1);
  -webkit-backdrop-filter: blur(var(--blur)) saturate(1.1);
  border-top: 1px solid var(--line);
  border-radius: 0 0 var(--radius) var(--radius); pointer-events: none;
  height: var(--foot-h); min-height: var(--foot-h);
}
/* ── 名字栏（独立毛玻璃） ── */
#chat .mes .mes_block .ch_name {
  position: relative; display: flex; align-items: center;
  flex-wrap: nowrap; gap: 0.4rem; border: none; margin: 0; width: 100%;
  box-sizing: border-box; min-height: calc(var(--avatar) / 2 + 1.2rem);
  padding: 0.75rem var(--pad) 0.5rem calc(var(--pad) + var(--avatar) + 0.9rem);
  background: var(--card-head);
  backdrop-filter: blur(calc(var(--blur) + 4px)) saturate(1.2);
  -webkit-backdrop-filter: blur(calc(var(--blur) + 4px)) saturate(1.2);
}
#chat .mes .mes_block .ch_name::after {
  content: ''; position: absolute; bottom: 0;
  left: var(--pad); right: var(--pad); height: 1px;
  background: linear-gradient(90deg, transparent, rgba(0,0,0,0.06) 12%, rgba(0,0,0,0.06) 88%, transparent);
  pointer-events: none;
}
#chat .mes .ch_name .name_text {
  font: 600 0.93rem/1.3 var(--sans); color: var(--name);
  letter-spacing: -0.01em; flex-shrink: 0;
}
/* ⭕ 名字后装饰符 — 改 content 换符号 */
#chat .mes .ch_name .name_text::after {
  content: '✦'; font-size: 0.5rem; color: var(--meta);
  opacity: 0.55; vertical-align: middle; margin-left: 0.2rem;
}
#chat .mes .ch_name .timestamp {
  font: 400 0.68rem/1.3 var(--cjk); color: var(--meta);
  white-space: nowrap; opacity: 0.7; flex-shrink: 0;
}
#chat .mes .ch_name .mes_ghost { color: var(--meta); font-size: 0.7rem; opacity: 0.6 }
/* 按钮区 */
#chat .mes .ch_name :is(.mes_buttons, .mes_edit_buttons) {
  position: absolute; top: 50%; right: var(--pad);
  transform: translateY(-50%); gap: 0.3rem;
}
#chat .mes .ch_name .mes_buttons { opacity: 0.25 }
#chat .mes .ch_name :is(.mes_buttons, .mes_edit_buttons) .mes_button {
  font-size: 0.85rem; padding: 0.1rem; color: var(--ink);
  opacity: 0.5; background: none; border: none;
}
/* ── 正文（独立毛玻璃，核心效果） ── */
#chat .mes .mes_block .mes_text {
  margin: 0;
  padding: 0.9rem calc(var(--pad) + 0.1rem) 1rem;
  font: 400 0.92rem/1.85 var(--cjk);
  color: var(--ink);
  background: var(--card-body);
  backdrop-filter: blur(var(--blur)) saturate(1.3);
  -webkit-backdrop-filter: blur(var(--blur)) saturate(1.3);
  overflow-wrap: break-word; word-break: break-word;
}
#chat .mes .mes_text p { margin: 0.35em 0 }
#chat .mes .mes_text :is(em, i) { color: var(--meta); font-style: italic; letter-spacing: 0.01em }
#chat .mes .mes_text :is(strong, b) { color: var(--name); font-weight: 600 }
#chat .mes .mes_text :is(s, del) { color: #bbb; text-decoration-color: rgba(0,0,0,0.12) }
/* 引用块 */
#chat .mes .mes_text :is(blockquote, q) {
  border: none;
  padding: 0.25rem 0.9rem; margin: 0.3rem 0.2rem;
  color: var(--ink-soft); font-style: italic; font-size: 0.88rem; line-height: 1.55;
  background: rgba(242,243,247,0.85);
  border-radius: 6px; box-shadow:
    0 1px 2px rgba(0,0,0,0.05),
    0 2px 8px rgba(0,0,0,0.03),
    inset 0 0 0 1px rgba(0,0,0,0.04);
}
#chat .mes .mes_text :is(blockquote, q)::before { display: none }
#chat .mes .mes_text :is(blockquote, q) p { margin: 0.1em 0 }
/* 行内代码 */
#chat .mes .mes_text code {
  font-family: var(--mono); font-size: 0.76rem;
  background: rgba(0,0,0,0.04); color: var(--ink-soft);
  padding: 0.15rem 0.5rem; border-radius: 5px;
  border: 1px solid rgba(0,0,0,0.04); letter-spacing: -0.01em;
}
/* 代码块 */
#chat .mes .mes_text pre {
  position: relative; margin: 0.8rem 0; padding: 0;
  border-radius: 10px; overflow: hidden;
  background: rgba(30,30,30,0.9);
  backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px);
  border: 1px solid rgba(255,255,255,0.06);
  box-shadow: 0 2px 8px rgba(0,0,0,0.08), inset 0 1px 0 rgba(255,255,255,0.04);
}
#chat .mes .mes_text pre code {
  display: block; padding: 1rem 1.15rem;
  background: none; border: none; border-radius: 0;
  color: #ccc; font-size: 0.78rem; line-height: 1.65;
  overflow-x: auto; white-space: pre; letter-spacing: 0;
}
#chat .mes .mes_text hr {
  border: none; height: 1px; margin: 1.2rem 0;
  background: linear-gradient(90deg, transparent, rgba(0,0,0,0.08) 20%, rgba(0,0,0,0.08) 80%, transparent);
}
#chat .mes .mes_text :is(ul, ol) { padding-left: 1.4rem; margin: 0.4rem 0 }
#chat .mes .mes_text li { margin: 0.2rem 0; line-height: 1.75 }
#chat .mes .mes_text ul li::marker { color: var(--meta); opacity: 0.5 }
#chat .mes .mes_text ol li::marker { color: var(--meta); font-size: 0.82rem; font-weight: 500 }
/* 编辑框 */
#chat .mes .mes_block > textarea {
  width: 100%; min-height: 8rem;
  padding: 0.85rem calc(var(--pad) + 0.1rem); margin: 0;
  background: rgba(255,255,255,0.55);
  backdrop-filter: blur(var(--blur));
  -webkit-backdrop-filter: blur(var(--blur));
  border: none; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line);
  border-radius: 0; color: var(--ink);
  font: 400 0.88rem/1.7 var(--cjk); resize: vertical; box-sizing: border-box;
}
#chat .mes .mes_block > textarea:focus { outline: none; background: rgba(255,255,255,0.68) }
/* ── 思维链（与正文统一） ── */
#chat .mes .mes_reasoning_details {
  margin: 0 !important; padding: 0 !important; border: none !important; border-radius: 0 !important;
  background: var(--card-body) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}
#chat .mes .mes_reasoning_details summary {
  padding: 0.5rem calc(var(--pad) + 0.1rem) !important;
  background: transparent !important; border: none !important; cursor: pointer;
}
.mes_reasoning_arrow { display: none }
.mes_reasoning_header_title { font-size: 0 }
/* ⭕ 思维链标题文字 — 改 content */
.mes_reasoning_header_title::before {
  content: 'thinking…'; color: var(--meta);
  font: 400 0.72rem/1 var(--cjk); letter-spacing: 0.04em;
}
#chat .mes .mes_reasoning {
  padding: 0.5rem calc(var(--pad) + 0.1rem) 0.65rem;
  color: var(--meta); font: 400 0.78rem/1.6 var(--cjk);
}
/* 隐藏思维链按钮和滚动条 */
.mes_reasoning_actions { display: none !important }
.mes_reasoning { scrollbar-width: none !important; overflow: -moz-scrollbars-none }
.mes_reasoning::-webkit-scrollbar { display: none !important }

/* 思维链头部去黑底，改透明药丸 */
.mes_reasoning_header {
  background: rgba(255,255,255,0.25) !important;
  border: 1px solid rgba(255,255,255,0.3) !important;
  border-radius: 20px !important;
  padding: 4px 12px !important;
  margin: 6px 0 !important;
  display: inline-flex !important;
  backdrop-filter: blur(8px) !important;
  -webkit-backdrop-filter: blur(8px) !important;
}
/* 思维链左侧黑条去掉 */
.mes_reasoning {
  border-left: none !important;
  border: none !important;
}

/* ── 输入区域 ── */
#form_sheld {
  width: 100%; max-width: none; margin: 0;
  background: rgba(255,255,255,0.88) !important;
  border-top: 1px solid var(--line);
  box-shadow: 0 -1px 12px rgba(0,0,0,0.02);
  backdrop-filter: blur(22px); -webkit-backdrop-filter: blur(22px);
}
#send_form {
  width: 100%; max-width: 560px; margin: 0 auto;
  padding: 0.5rem var(--pad);
  background: var(--card) !important;
  border-radius: 24px !important;
  border: 1px solid rgba(255,255,255,0.5) !important;
  box-shadow: var(--shadow) !important; gap: 0.5rem; box-sizing: border-box; align-items: center;
}
#send_textarea {
  min-height: 2.6rem; padding: 0.6rem 1rem;
  background: rgba(242,243,247,0.6) !important;
  border: none !important; border-radius: 20px !important;
  outline: none; color: var(--ink);
  font: 400 0.88rem/1.5 var(--cjk); resize: none;
  box-sizing: border-box;
}
#send_textarea:focus { outline: none }
#send_textarea::placeholder { color: var(--meta); font: 400 0.82rem var(--cjk); opacity: 0.7 }
/* ── QR 悬停滑出 ── */
#qr--bar {
  max-height: 0; overflow: hidden; background: none;
  transition: max-height 0.4s ease, padding 0.4s ease; padding: 0;
}
#form_sheld:hover #qr--bar { max-height: 80px; padding: 0.3rem 0.5rem }
/* ── 杂项 ── */
.mes_stop { background: transparent !important; border: none !important; box-shadow: none !important }
a, a:visited, a:active { color: var(--accent); text-decoration: none }
a:hover { color: #333 }
:is(#options_button, #extensionsMenuButton, .mes_stop,
#dialogue_del_mes, #rightSendForm > div, #leftSendForm > div) {
  color: var(--ink); opacity: 0.45;
}
/* ── 移动端适配 ── */
@media (max-width: 768px) and (pointer: coarse) {
  :root { --radius: 10px; --avatar: 3.8rem; --pad: 0.9rem; --banner-h: 85px }
  #chat { padding: 0.5rem 0.4rem }
  #chat .mes { max-width: 92%; margin-bottom: 0.6rem !important }
